#include <iostream>
using namespace std;

int main() {
    int x;
    cin >> x;
    if (0 <= x <= 10) {                      // MAL: siempre es cierto
        cout << "Versio dolenta: " << x << " es dins [0, 10]" << endl;
    }
    if (0 <= x && x <= 10) {                 // BIEN
        cout << "Versio bona: " << x << " es dins [0, 10]" << endl;
    } else {
        cout << "Versio bona: " << x << " es fora de [0, 10]" << endl;
    }
    return 0;
}

