#include <iostream>
#include <iomanip>
using namespace std;

int main() {
    int NO;
    char TPO;
    double PD = 0, PE = 0;      // precios según el tipo
    cin >> NO >> TPO;

    int ND = NO / 12;           // cajas enteras
    int NE = NO % 12;           // huevos sueltos

    switch (TPO) {
        case 'A':
            PD = 3;
            PE = 0.30;
            break;
        case 'B':
            PD = 2.5;
            PE = 0.25;
            break;
        case 'C':
            PD = 2;
            PE = 0.20;
            break;
    }

    double IMP = ND * PD + NE * PE;
    cout << "Dotzenes: " << ND << endl;
    cout << "Escadussers: " << NE << endl;
    cout << fixed << setprecision(2) << "IMPORT: " << IMP << endl;
    return 0;
}

